/** Typed analytical read model. SQL aggregates latency in PostgreSQL; temporal availability remains delegated to R02.2. */
@Service @Transactional(readOnly = true)
public class RelatorioService {
 private static final int DIAS_HISTORICO_DIARIO = 30;
 private final String timezone;
 private final NamedParameterJdbcTemplate jdbc; private final EquipamentoRepository equipamentos; private final DisponibilidadeEquipamentoTemporalService temporal; private final UnidadeRepository unidades; private final MonitorRepository monitores; private final TipoEquipamentoRepository tipos; private final IncidenteRepository incidentesRepository; private final DisponibilidadeSqlRepository disponibilidadeSql;
 public RelatorioService(NamedParameterJdbcTemplate jdbc, EquipamentoRepository equipamentos, DisponibilidadeEquipamentoTemporalService temporal, UnidadeRepository unidades, MonitorRepository monitores, TipoEquipamentoRepository tipos, IncidenteRepository incidentesRepository, DisponibilidadeSqlRepository disponibilidadeSql, @Value("${app.reports.timezone:America/Sao_Paulo}") String timezone){this.timezone=timezone;this.jdbc=jdbc;this.equipamentos=equipamentos;this.temporal=temporal;this.unidades=unidades;this.monitores=monitores;this.tipos=tipos;this.incidentesRepository=incidentesRepository;this.disponibilidadeSql=disponibilidadeSql;}
 private int valid(Instant a,Instant b,int days,int page,int size){if(a==null||b==null||a.isAfter(b)||Duration.between(a,b).compareTo(Duration.ofDays(days))>0)throw new IllegalArgumentException("Periodo invalido");if(page<0||size<1)throw new IllegalArgumentException("Paginacao invalida");return Math.min(size,100);}
 private void filters(Long unidadeId,Long equipamentoId,Long monitorId,Long tipoId,Long incidenteId){
  if(unidadeId!=null&&!unidades.existsById(unidadeId))throw new RecursoNaoEncontradoException("Unidade nao encontrada"); if(equipamentoId!=null&&!equipamentos.existsById(equipamentoId))throw new RecursoNaoEncontradoException("Equipamento nao encontrado"); if(monitorId!=null&&!monitores.existsById(monitorId))throw new RecursoNaoEncontradoException("Monitor nao encontrado"); if(tipoId!=null&&!tipos.existsById(tipoId))throw new RecursoNaoEncontradoException("Tipo de equipamento nao encontrado"); if(incidenteId!=null&&!incidentesRepository.existsById(incidenteId))throw new RecursoNaoEncontradoException("Incidente nao encontrado");
  var equipamento=equipamentoId==null?null:equipamentos.findById(equipamentoId).orElseThrow(); var monitor=monitorId==null?null:monitores.findById(monitorId).orElseThrow();
  if(equipamento!=null&&unidadeId!=null&&!Objects.equals(equipamento.getUnidade().getId(),unidadeId))throw new IllegalArgumentException("Equipamento nao pertence a unidade"); if(equipamento!=null&&tipoId!=null&&!Objects.equals(equipamento.getTipoEquipamento().getId(),tipoId))throw new IllegalArgumentException("Equipamento nao pertence ao tipo"); if(monitor!=null&&equipamentoId!=null&&!Objects.equals(monitor.getEquipamento().getId(),equipamentoId))throw new IllegalArgumentException("Monitor nao pertence ao equipamento"); if(monitor!=null&&unidadeId!=null&&!Objects.equals(monitor.getEquipamento().getUnidade().getId(),unidadeId))throw new IllegalArgumentException("Monitor nao pertence a unidade"); }
 private String order(String sort,Map<String,String> allowed,String fallback){String value=(sort==null||sort.isBlank())?fallback:sort;String[] parts=value.split(",",-1);if(parts.length!=2||!allowed.containsKey(parts[0])||!(parts[1].equalsIgnoreCase("asc")||parts[1].equalsIgnoreCase("desc")))throw new IllegalArgumentException("Sort invalido");return allowed.get(parts[0])+" "+parts[1].toUpperCase(Locale.ROOT)+" NULLS LAST";}
 public String validarExportacaoDisponibilidade(Instant inicio,Instant fim,Long unidadeId,Long equipamentoId,Long monitorId,Long tipo,String sort){valid(inicio,fim,365,0,1);filters(unidadeId,equipamentoId,monitorId,tipo,null);return order(sort,Map.of("equipamentoNome","equipamento_nome","unidadeNome","unidade_nome","monitorNome","monitor_nome","disponibilidadePercentual","disponibilidade","tempoIndisponivelSegundos","tempo_indisponivel","tempoMonitoradoSegundos","tempo_monitorado","incidentes","incidentes"),"equipamentoNome,asc");}
 public String validarExportacaoUnidades(Instant inicio,Instant fim,Long unidadeId,String sort){valid(inicio,fim,365,0,1);filters(unidadeId,null,null,null,null);return order(sort,Map.of("unidadeNome","unidade_nome","equipamentosTotal","equipamentos_total","equipamentosMonitorados","equipamentos_monitorados","equipamentosSemMonitoramento","equipamentos_sem_monitoramento","tempoIndisponivelSegundos","tempo_indisponivel","disponibilidadePercentual","disponibilidade","incidentes","incidentes"),"unidadeNome,asc");}
 public String validarExportacaoIncidentes(Instant inicio,Instant fim,Long unidadeId,Long equipamentoId,Long monitorId,String sort){valid(inicio,fim,365,0,1);filters(unidadeId,equipamentoId,monitorId,null,null);return order(sort,Map.of("iniciadoEm","iniciado_em","encerradoEm","encerrado_em","duracaoSegundosNoPeriodo","duracao","status","status","unidadeNome","unidade_nome","equipamentoNome","equipamento_nome","monitorNome","monitor_nome"),"iniciadoEm,desc");}
 public String validarExportacaoMedicoes(Instant inicio,Instant fim,Long unidadeId,Long equipamentoId,Long monitorId,String sort){valid(inicio,fim,31,0,1);filters(unidadeId,equipamentoId,monitorId,null,null);return order(sort,Map.of("executadoEm","executado_em","status","status","latenciaMs","latencia_ms","unidadeNome","unidade_nome","equipamentoNome","equipamento_nome","monitorNome","monitor_nome"),"executadoEm,desc");}
 public String validarExportacaoLatencia(Instant inicio,Instant fim,Long unidadeId,Long equipamentoId,Long monitorId,String sort){valid(inicio,fim,90,0,1);filters(unidadeId,equipamentoId,monitorId,null,null);return order(sort,Map.of("unidadeNome","unidade_nome","equipamentoNome","equipamento_nome","monitorNome","monitor_nome","minLatenciaMs","min_latencia","avgLatenciaMs","avg_latencia","maxLatenciaMs","max_latencia","count","quantidade"),"monitorNome,asc");}
 public String validarExportacaoNotificacoes(Instant inicio,Instant fim,Long incidenteId,String sort){valid(inicio,fim,365,0,1);filters(null,null,null,null,incidenteId);return order(sort,Map.of("createdAt","created_at","enviadoEm","enviado_em","status","status","canal","canal","tipoEvento","tipo_evento","tentativas","tentativas"),"createdAt,desc");}
 private MapSqlParameterSource params(Instant a, Instant b){return new MapSqlParameterSource().addValue("inicio",Timestamp.from(a)).addValue("fim",Timestamp.from(b));}
 static Instant instant(ResultSet row, String column) throws java.sql.SQLException { OffsetDateTime value=row.getObject(column, OffsetDateTime.class); return value == null ? null : value.toInstant(); }
 static Integer p95(Number value) { return value == null ? null : BigDecimal.valueOf(value.doubleValue()).add(new BigDecimal("0.000000001")).setScale(0, RoundingMode.HALF_UP).intValueExact(); }
 private <T> PaginaResposta<T> page(String sql, String order, MapSqlParameterSource p, int page, int size, RowMapper<T> mapper){Long total=jdbc.queryForObject("select count(*) from ("+sql+") report_count",p,Long.class);var rows=jdbc.query(sql+" order by "+order+" limit :limit offset :offset",p.addValue("limit",size).addValue("offset",page*size),mapper);int pages=(int)((total+size-1)/size);return new PaginaResposta<>(rows,page,size,total,pages,page==0,page>=pages-1);}
 private <T> PaginaResposta<T> page(String sql, MapSqlParameterSource p, int page, int size, RowMapper<T> mapper){Long total=jdbc.queryForObject("select count(*) from ("+sql+") report_count",p,Long.class);var rows=jdbc.query(sql+" limit :limit offset :offset",p.addValue("limit",size).addValue("offset",page*size),mapper);int pages=(int)((total+size-1)/size);return new PaginaResposta<>(rows,page,size,total,pages,page==0,page>=pages-1);}

 public PaginaResposta<DisponibilidadeEquipamentoResponse> disponibilidade(Instant inicio,Instant fim,Long unidadeId,Long equipamentoId,Long monitorId,Long tipo,int page,int size,String sort){
  size=valid(inicio,fim,365,page,size); filters(unidadeId,equipamentoId,monitorId,tipo,null); String sqlOrder=order(sort,Map.of("equipamentoNome","equipamento_nome","unidadeNome","unidade_nome","monitorNome","monitor_nome","disponibilidadePercentual","disponibilidade","tempoIndisponivelSegundos","tempo_indisponivel","tempoMonitoradoSegundos","tempo_monitorado","incidentes","incidentes"),"equipamentoNome,asc"); if(disponibilidadeSql!=null)return disponibilidadeSql.equipamentos(inicio,fim,unidadeId,equipamentoId,monitorId,tipo,page,size,sqlOrder); List<Equipamento> es=equipamentoId!=null?equipamentos.findById(equipamentoId).map(List::of).orElseThrow():unidadeId!=null?equipamentos.findAllByUnidadeId(unidadeId):equipamentos.findAll();
  var porId=es.stream().collect(Collectors.toMap(Equipamento::getId,x->x)); var all=temporal.calcularTodos(es,inicio,fim).stream().filter(r->monitorId==null||Objects.equals(r.monitorId(),monitorId)).map(r->{var e=porId.get(r.equipamentoId());return new DisponibilidadeEquipamentoResponse(r.equipamentoId(),r.equipamentoNome(),e.getUnidade().getId(),e.getUnidade().getNome(),r.monitorId(),r.monitorNome(),r.monitorId()==null?null:"ICMP",inicio,fim,r.estadoAnalitico(),r.qualidadeJanela(),r.tempoMonitoradoSegundos(),r.tempoIndisponivelSegundos(),r.tempoDisponivelSegundos(),r.disponibilidadePercentual(),r.incidentes());}).toList();
  int from=Math.min(page*size,all.size()),to=Math.min(from+size,all.size());return new PaginaResposta<>(all.subList(from,to),page,size,all.size(),(all.size()+size-1)/size,page==0,to==all.size()); }

 /** Serie diaria dos ultimos 30 dias de calendario local: 00:00 de D-29 ate agora. Somente o ultimo dia e parcial. */
 public List<DisponibilidadeDiariaUnidadeResponse> disponibilidadeDiariaUnidade(Long unidadeId){
  filters(unidadeId,null,null,null,null); ZoneId zona=ZoneId.of(timezone); ZonedDateTime agora=ZonedDateTime.now(zona);
  Instant inicio=agora.toLocalDate().minusDays(DIAS_HISTORICO_DIARIO-1).atStartOfDay(zona).toInstant();
  return disponibilidadeSql.diariaPorUnidade(inicio,agora.toInstant(),unidadeId); }

 public PaginaResposta<DisponibilidadeUnidadeResponse> unidades(Instant inicio,Instant fim,Long unidadeId,int page,int size,String sort){
  size=valid(inicio,fim,365,page,size); filters(unidadeId,null,null,null,null); String sqlOrder=order(sort,Map.of("unidadeNome","unidade_nome","equipamentosTotal","equipamentos_total","equipamentosMonitorados","equipamentos_monitorados","equipamentosSemMonitoramento","equipamentos_sem_monitoramento","tempoIndisponivelSegundos","tempo_indisponivel","disponibilidadePercentual","disponibilidade","incidentes","incidentes"),"unidadeNome,asc"); if(disponibilidadeSql!=null)return disponibilidadeSql.unidades(inicio,fim,unidadeId,page,size,sqlOrder); List<Equipamento> es=unidadeId==null?equipamentos.findAll():equipamentos.findAllByUnidadeId(unidadeId); var porUnidade=es.stream().collect(Collectors.groupingBy(e->e.getUnidade().getId())); var results=temporal.calcularTodos(es,inicio,fim).stream().collect(Collectors.groupingBy(r->porUnidade.entrySet().stream().filter(x->x.getValue().stream().anyMatch(e->e.getId().equals(r.equipamentoId()))).findFirst().orElseThrow().getKey()));
  var all=porUnidade.entrySet().stream().map(entry->{var equipamentosUnidade=entry.getValue();var rs=results.getOrDefault(entry.getKey(),List.of()); var byEquip=rs.stream().collect(Collectors.groupingBy(DisponibilidadeEquipamentoTemporalResponse::equipamentoId)); long monitorados=byEquip.values().stream().filter(x->x.stream().anyMatch(r->r.estadoAnalitico()==EstadoAnalitico.CALCULADO)).count();long semMonitoramento=byEquip.values().stream().filter(x->x.stream().allMatch(r->r.estadoAnalitico()==EstadoAnalitico.SEM_MONITORAMENTO)).count();long semDados=byEquip.values().stream().filter(x->x.stream().noneMatch(r->r.estadoAnalitico()==EstadoAnalitico.CALCULADO)&&x.stream().anyMatch(r->r.estadoAnalitico()==EstadoAnalitico.SEM_DADOS)).count(); long monitorado=rs.stream().filter(r->r.estadoAnalitico()==EstadoAnalitico.CALCULADO).mapToLong(r->r.tempoMonitoradoSegundos()).sum();long indisponivel=rs.stream().filter(r->r.estadoAnalitico()==EstadoAnalitico.CALCULADO).mapToLong(r->r.tempoIndisponivelSegundos()).sum();var calculado=monitorado>0;var percentual=calculado?BigDecimal.valueOf(monitorado-indisponivel).multiply(BigDecimal.valueOf(100)).divide(BigDecimal.valueOf(monitorado),2,RoundingMode.HALF_UP):null;var estado=calculado?EstadoAnalitico.CALCULADO:(semDados>0?EstadoAnalitico.SEM_DADOS:EstadoAnalitico.SEM_MONITORAMENTO);var u=equipamentosUnidade.getFirst().getUnidade();return new DisponibilidadeUnidadeResponse(u.getId(),u.getNome(),inicio,fim,estado,equipamentosUnidade.size(),monitorados,semMonitoramento,semDados,calculado?monitorado:null,calculado?indisponivel:null,calculado?monitorado-indisponivel:null,percentual,rs.stream().mapToLong(DisponibilidadeEquipamentoTemporalResponse::incidentes).sum());}).toList();int from=Math.min(page*size,all.size()),to=Math.min(from+size,all.size());return new PaginaResposta<>(all.subList(from,to),page,size,all.size(),(all.size()+size-1)/size,page==0,to==all.size()); }

 public PaginaResposta<HistoricoIncidenteResponse> incidentes(Instant inicio,Instant fim,Long unidadeId,Long equipamentoId,Long monitorId,StatusIncidente status,int page,int size,String sort){size=valid(inicio,fim,365,page,size);filters(unidadeId,equipamentoId,monitorId,null,null);String ord=order(sort,Map.of("iniciadoEm","iniciado_em","encerradoEm","encerrado_em","duracaoSegundosNoPeriodo","duracao","status","status","unidadeNome","unidade_nome","equipamentoNome","equipamento_nome","monitorNome","monitor_nome"),"iniciadoEm,desc");var p=params(inicio,fim).addValue("unidadeId",unidadeId).addValue("equipamentoId",equipamentoId).addValue("monitorId",monitorId).addValue("status",status==null?null:status.name());String sql="select i.id incidente_id,u.id unidade_id,u.nome unidade_nome,e.id equipamento_id,e.nome equipamento_nome,m.id monitor_id,m.nome monitor_nome,m.tipo tipo_monitor,i.status,i.iniciado_em,i.encerrado_em,extract(epoch from greatest(interval '0', least(coalesce(i.encerrado_em,:fim),:fim)-greatest(i.iniciado_em,:inicio)))::bigint duracao,i.motivo,i.observacao from incidente i join monitor m on m.id=i.monitor_id join equipamento e on e.id=m.equipamento_id join unidade u on u.id=e.unidade_id where i.iniciado_em<:fim and (i.encerrado_em is null or i.encerrado_em>=:inicio) and (cast(:unidadeId as bigint) is null or u.id=:unidadeId) and (cast(:equipamentoId as bigint) is null or e.id=:equipamentoId) and (cast(:monitorId as bigint) is null or m.id=:monitorId) and (cast(:status as varchar) is null or i.status=:status)";return page(sql,ord,p,page,size,(r,n)->new HistoricoIncidenteResponse(r.getLong("incidente_id"),r.getLong("unidade_id"),r.getString("unidade_nome"),r.getLong("equipamento_id"),r.getString("equipamento_nome"),r.getLong("monitor_id"),r.getString("monitor_nome"),r.getString("tipo_monitor"),r.getString("status"),instant(r,"iniciado_em"),instant(r,"encerrado_em"),r.getLong("duracao"),r.getString("motivo"),r.getString("observacao")));}
 public PaginaResposta<HistoricoMedicaoResponse> medicoes(Instant inicio,Instant fim,Long unidadeId,Long equipamentoId,Long monitorId,StatusMedicao status,int page,int size,String sort){size=valid(inicio,fim,31,page,size);filters(unidadeId,equipamentoId,monitorId,null,null);String ord=order(sort,Map.of("executadoEm","executado_em","status","status","latenciaMs","latencia_ms","unidadeNome","unidade_nome","equipamentoNome","equipamento_nome","monitorNome","monitor_nome"),"executadoEm,desc");var p=params(inicio,fim).addValue("unidadeId",unidadeId).addValue("equipamentoId",equipamentoId).addValue("monitorId",monitorId).addValue("status",status==null?null:status.name());String sql="select md.id medicao_id,u.id unidade_id,u.nome unidade_nome,e.id equipamento_id,e.nome equipamento_nome,m.id monitor_id,m.nome monitor_nome,m.tipo tipo_monitor,md.status,md.latencia_ms,md.executado_em from medicao md join monitor m on m.id=md.monitor_id join equipamento e on e.id=m.equipamento_id join unidade u on u.id=e.unidade_id where md.executado_em>=:inicio and md.executado_em<=:fim and (cast(:unidadeId as bigint) is null or u.id=:unidadeId) and (cast(:equipamentoId as bigint) is null or e.id=:equipamentoId) and (cast(:monitorId as bigint) is null or m.id=:monitorId) and (cast(:status as varchar) is null or md.status=:status)";return page(sql,ord,p,page,size,(r,n)->new HistoricoMedicaoResponse(r.getLong("medicao_id"),r.getLong("unidade_id"),r.getString("unidade_nome"),r.getLong("equipamento_id"),r.getString("equipamento_nome"),r.getLong("monitor_id"),r.getString("monitor_nome"),r.getString("tipo_monitor"),r.getString("status"),(Integer)r.getObject("latencia_ms"),instant(r,"executado_em")));}
 public PaginaResposta<LatenciaIcmpResponse> latencia(Instant inicio,Instant fim,Long unidadeId,Long equipamentoId,Long monitorId,int page,int size,String sort){size=valid(inicio,fim,90,page,size);filters(unidadeId,equipamentoId,monitorId,null,null);String ord=order(sort,Map.of("unidadeNome","unidade_nome","equipamentoNome","equipamento_nome","monitorNome","monitor_nome","minLatenciaMs","min_latencia","avgLatenciaMs","avg_latencia","maxLatenciaMs","max_latencia","count","quantidade"),"monitorNome,asc");var p=params(inicio,fim).addValue("unidadeId",unidadeId).addValue("equipamentoId",equipamentoId).addValue("monitorId",monitorId);String sql="select u.id unidade_id,u.nome unidade_nome,e.id equipamento_id,e.nome equipamento_nome,m.id monitor_id,m.nome monitor_nome,min(md.latencia_ms) min_latencia,round(avg(md.latencia_ms),2) avg_latencia,max(md.latencia_ms) max_latencia,count(md.id) quantidade,percentile_cont(0.95) within group(order by md.latencia_ms) p95 from monitor m join equipamento e on e.id=m.equipamento_id join unidade u on u.id=e.unidade_id left join medicao md on md.monitor_id=m.id and md.status='SUCESSO' and md.latencia_ms is not null and md.executado_em>=:inicio and md.executado_em<=:fim where m.tipo='ICMP' and (cast(:unidadeId as bigint) is null or u.id=:unidadeId) and (cast(:equipamentoId as bigint) is null or e.id=:equipamentoId) and (cast(:monitorId as bigint) is null or m.id=:monitorId) group by u.id,u.nome,e.id,e.nome,m.id,m.nome order by "+ord;return page(sql,p,page,size,(r,n)->new LatenciaIcmpResponse(r.getLong("unidade_id"),r.getString("unidade_nome"),r.getLong("equipamento_id"),r.getString("equipamento_nome"),r.getLong("monitor_id"),r.getString("monitor_nome"),inicio,fim,(Integer)r.getObject("min_latencia"),r.getBigDecimal("avg_latencia"),(Integer)r.getObject("max_latencia"),r.getLong("quantidade"),p95((Number)r.getObject("p95"))));}
 /** Mesma janela e filtros da latencia por monitor, agregada em uma linha por unidade: media ponderada pelas medicoes. */
 public PaginaResposta<LatenciaUnidadeResponse> latenciaUnidades(Instant inicio,Instant fim,Long unidadeId,int page,int size,String sort){size=valid(inicio,fim,90,page,size);filters(unidadeId,null,null,null,null);String ord=order(sort,Map.of("unidadeNome","unidade_nome","minLatenciaMs","min_latencia","avgLatenciaMs","avg_latencia","maxLatenciaMs","max_latencia","count","quantidade"),"unidadeNome,asc");var p=params(inicio,fim).addValue("unidadeId",unidadeId);String sql="select u.id unidade_id,u.nome unidade_nome,min(md.latencia_ms) min_latencia,round(avg(md.latencia_ms),2) avg_latencia,max(md.latencia_ms) max_latencia,count(md.id) quantidade from monitor m join equipamento e on e.id=m.equipamento_id join unidade u on u.id=e.unidade_id left join medicao md on md.monitor_id=m.id and md.status='SUCESSO' and md.latencia_ms is not null and md.executado_em>=:inicio and md.executado_em<=:fim where m.tipo='ICMP' and (cast(:unidadeId as bigint) is null or u.id=:unidadeId) group by u.id,u.nome order by "+ord;return page(sql,p,page,size,(r,n)->new LatenciaUnidadeResponse(r.getLong("unidade_id"),r.getString("unidade_nome"),inicio,fim,(Integer)r.getObject("min_latencia"),r.getBigDecimal("avg_latencia"),(Integer)r.getObject("max_latencia"),r.getLong("quantidade")));}
 public PaginaResposta<HistoricoNotificacaoResponse> notificacoes(Instant inicio,Instant fim,Long incidenteId,StatusNotificacao status,CanalNotificacao canal,TipoEventoNotificacao tipo,int page,int size,String sort){size=valid(inicio,fim,365,page,size);filters(null,null,null,null,incidenteId);String ord=order(sort,Map.of("createdAt","created_at","enviadoEm","enviado_em","status","status","canal","canal","tipoEvento","tipo_evento","tentativas","tentativas"),"createdAt,desc");var p=params(inicio,fim).addValue("incidenteId",incidenteId).addValue("status",status==null?null:status.name()).addValue("canal",canal==null?null:canal.name()).addValue("tipo",tipo==null?null:tipo.name());String sql="select id,incidente_id,canal,tipo_evento,status,tentativas,enviado_em,erro,created_at from notificacao where created_at>=:inicio and created_at<=:fim and (cast(:incidenteId as bigint) is null or incidente_id=:incidenteId) and (cast(:status as varchar) is null or status=:status) and (cast(:canal as varchar) is null or canal=:canal) and (cast(:tipo as varchar) is null or tipo_evento=:tipo) order by "+ord;return page(sql,p,page,size,(r,n)->new HistoricoNotificacaoResponse(r.getLong("id"),r.getLong("incidente_id"),r.getString("canal"),r.getString("tipo_evento"),r.getString("status"),r.getInt("tentativas"),instant(r,"enviado_em"),r.getString("erro"),instant(r,"created_at")));}
}
